attempts.sql:
WITH spotlight AS (
  SELECT id, isTextless FROM cards WHERE isStorySpotlight = 1
), stats AS (
  SELECT COUNT(*) AS total, SUM(CASE WHEN isTextless = 1 THEN 1 ELSE 0 END) AS textless FROM spotlight
)
SELECT percentage, id
FROM (
  SELECT 100.0 * textless / NULLIF(total, 0) AS percentage, NULL AS id, 0 AS sort_key FROM stats
  UNION ALL
  SELECT NULL AS percentage, id, 1 AS sort_key FROM spotlight WHERE isTextless = 1
)
ORDER BY sort_key, id;

